import fs from 'fs';
import path from 'path';
import { delimiter } from 'path';
import {
  EXECUTABLE_RUNNER_VENDORS,
  RUNNER_VENDOR_BINARIES,
  type RunnerVendor,
} from './runnerSelection';
import { createLogger } from '../utils/logger';

const log = createLogger('CallerRunnerPaths');


export const CALLER_RUNNER_PATHS_ENV = 'RIVET_CALLER_RUNNER_PATHS';

export type DeclaredRunnerPaths = Partial<Record<RunnerVendor, string>>;

export const resolveBinaryPathOnPath = (
  binary: string,
  env: NodeJS.ProcessEnv = process.env,
): string | undefined => {
  for (const dir of (env.PATH ?? '').split(delimiter)) {
    if (!dir) continue;
    const candidate = path.resolve(dir, binary);
    try {
      fs.accessSync(candidate, fs.constants.X_OK);
      return candidate;
    } catch {
    }
  }
  return undefined;
};

const isVerifiedDeclaration = (
  vendor: RunnerVendor,
  value: unknown,
): value is string => {
  if (typeof value !== 'string' || !path.isAbsolute(value)) return false;
  if (path.basename(value) !== RUNNER_VENDOR_BINARIES[vendor]) return false;
  try {
    fs.accessSync(value, fs.constants.X_OK);
    return true;
  } catch {
    return false;
  }
};

export const resolveCallerRunnerPaths = (
  env: NodeJS.ProcessEnv = process.env,
): DeclaredRunnerPaths => {
  const resolved: DeclaredRunnerPaths = {};
  for (const vendor of EXECUTABLE_RUNNER_VENDORS) {
    const binaryPath = resolveBinaryPathOnPath(
      RUNNER_VENDOR_BINARIES[vendor],
      env,
    );
    if (binaryPath) resolved[vendor] = binaryPath;
  }
  return resolved;
};

export const verifiedRunnerPaths = (
  record: unknown,
  origin: string,
): DeclaredRunnerPaths => {
  if (typeof record !== 'object' || record === null || Array.isArray(record)) {
    return {};
  }
  const verified: DeclaredRunnerPaths = {};
  for (const vendor of EXECUTABLE_RUNNER_VENDORS) {
    const value = (record as Record<string, unknown>)[vendor];
    if (value === undefined) continue;
    if (isVerifiedDeclaration(vendor, value)) {
      verified[vendor] = value;
    } else {
      log.warn(`dropping unverifiable ${origin} runner path for ${vendor}`);
    }
  }
  return verified;
};

export const parseCallerRunnerPaths = (
  env: NodeJS.ProcessEnv = process.env,
): DeclaredRunnerPaths => {
  const raw = env[CALLER_RUNNER_PATHS_ENV];
  if (!raw) return {};
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    log.warn(`${CALLER_RUNNER_PATHS_ENV} is not valid JSON — ignoring`);
    return {};
  }
  return verifiedRunnerPaths(parsed, CALLER_RUNNER_PATHS_ENV);
};

export const callerRunnerPathsEnvEntry = (
  baseEnv: NodeJS.ProcessEnv = process.env,
): Record<string, string> => {
  const merged: DeclaredRunnerPaths = {
    ...resolveCallerRunnerPaths(baseEnv),
    ...parseCallerRunnerPaths(baseEnv),
  };
  return Object.keys(merged).length > 0
    ? { [CALLER_RUNNER_PATHS_ENV]: JSON.stringify(merged) }
    : {};
};
